fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"city\":\"Oslo\",\"temps\":[3.5,-1.25,0.75,4.0]}");
    let root: ToonNode = toon_root(doc);
    let temps: ToonNode = toon_key(root, "temps");
    let n: Int = toon_len(temps);
    let sum: Real = 0.0;
    let lo: Real = toon_real_value(toon_at(temps, 0));
    let hi: Real = lo;
    loop i in 0..n {
        let t: Real = toon_real_value(toon_at(temps, i));
        sum = sum + t;
        lo = min(lo, t);
        hi = max(hi, t);
    }
    fx {
        println(toon_get_text(root, "city"), ": ", n, " readings");
        println("avg=", formatfloat(sum / n, 2));
        println("min=", formatfloat(lo, 2), " max=", formatfloat(hi, 2));
    }
    toon_close(doc);
    ret;
}

@pure
fn clock(secs: Int) -> Text {
    let s: Int = secs % 60;
    let pad: Text = if s < 10 { "0" } else { "" };
    ret int_to_text(secs div 60) + ":" + pad + int_to_text(s);
}

fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"name\":\"Road Trip\",\"tracks\":[{\"title\":\"Highway\",\"secs\":245},{\"title\":\"Dust\",\"secs\":198},{\"title\":\"Coast\",\"secs\":312}]}");
    let root: ToonNode = toon_root(doc);
    let tracks: ToonNode = toon_key(root, "tracks");
    let total: Int = 0;
    fx { println(toon_get_text(root, "name"), " (", toon_len(tracks), " tracks)"); }
    loop i in 0..toon_len(tracks) {
        let track: ToonNode = toon_at(tracks, i);
        let secs: Int = toon_get_int(track, "secs");
        total = total + secs;
        fx { println(i + 1, ". ", toon_get_text(track, "title"), " ", clock(secs)); }
    }
    fx { println("total ", clock(total)); }
    toon_close(doc);
    ret;
}

