@pure
fn minutesOf(hhmm: Text) -> Int {
    let parts: Text[] = split(hhmm, ":");
    ret parse_int(parts[0]) * 60 + parse_int(parts[1]);
}

fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"route\":{\"number\":\"42\",\"from\":\"Depot\",\"to\":\"Harbor\"},\"departures\":[\"06:15\",\"07:40\",\"09:20\"],\"express\":true}");
    let root: ToonNode = toon_root(doc);
    let deps: ToonNode = toon_key(root, "departures");
    let kind: Text = if toon_get_bool_or(root, "express", false) { " express" } else { "" };
    fx {
        println("Route ", toon_get_text(root, "route.number"), kind, ": ",
                toon_get_text(root, "route.from"), " -> ", toon_get_text(root, "route.to"));
    }
    let prev: Int = 0;
    loop i in 0..toon_len(deps) {
        let t: Text = toon_text_value(toon_at(deps, i));
        let now: Int = minutesOf(t);
        if i == 0 {
            fx { println(t); }
        } else {
            fx { println(t, " (+", now - prev, " min)"); }
        }
        prev = now;
    }
    toon_close(doc);
    ret;
}

