const LOAN_DAYS: Int = 21;
const CENTS_PER_DAY: Int = 25;

fn main() -> Void {
    if !has_toon() {
        fx { println("TOON support unavailable"); }
        ret;
    }

    let doc: ToonDoc;
    fx {
        doc = toon_parse_file("loans.json");
    }
    let root: ToonNode = toon_root(doc);
    let overdue: Int = 0;

    loop i in 0..toon_len(root) {
        let loan: ToonNode = toon_at(root, i);
        let late: Int = toon_get_int_or(loan, "days_out", 0) - LOAN_DAYS;
        if late > 0 {
            overdue = overdue + 1;
            let fine: Real = late * CENTS_PER_DAY / 100.0;
            let title: Text = toon_get_text(loan, "title");
            fx {
                println(title, " | late ", late, " | fine ", fine:0:2);
            }
        }
    }

    fx {
        println("overdue ", overdue, " of ", toon_len(root));
    }
    toon_close(doc);
    ret;
}

