fn runLength(s: Text) -> Text {
    let ms: MStream = mstreamcreate();
    let n: Int = string_len(s);
    let i: Int = 0;
    loop i < n {
        let j: Int = i;
        loop j < n && s[j] == s[i] {
            j = j + 1;
        }
        mstreamappendbyte(ms, ord(s[i]));
        appendText(ms, int_to_text(j - i));
        i = j;
    }
    let packed: Text = mstreambuffer(ms);
    mstreamfree(ms);
    ret packed;
}

