fn toBinary(n: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let bits: Int[] = [];
    let v: Int = n;
    loop v > 0 {
        bits = bits + [v % 2];
        v = v div 2;
    }
    let ms: MStream = mstreamcreate();
    loop i in length(bits) - 1..-1 step -1 {
        mstreamappendbyte(ms, 48 + bits[i]);
    }
    let out: Text = mstreambuffer(ms);
    mstreamfree(ms);
    ret out;
}

