fn main() -> Void {
    let scores: Int[] = [88, 92, 75, 64];
    let out: MStream = mstreamcreate();
    mstreamappendbyte(out, ord("["));
    loop i in 0..length(scores) {
        if i > 0 {
            mstreamappendbyte(out, ord(","));
        }
        appendText(out, int_to_text(scores[i]));
    }
    mstreamappendbyte(out, ord("]"));

    let back: MStream = mstreamcreate();
    fx {
        mstreamsavetofile(out, "scores.json");
        mstreamloadfromfile(back, "scores.json");
    }
    let doc: ToonDoc = toon_parse(mstreambuffer(back));
    let root: ToonNode = toon_root(doc);
    let n: Int = toon_len(root);
    let sum: Int = 0;
    let best: Int = 0;
    loop i in 0..n {
        let v: Int = toon_int_value(toon_at(root, i));
        sum = sum + v;
        best = max(best, v);
    }
    fx {
        println("saved ", mstreambuffer(back));
        println("n=", n, " sum=", sum, " max=", best);
    }
    toon_close(doc);
    mstreamfree(out);
    mstreamfree(back);
    ret;
}

