fn appendField(ms: MStream, value: Text) -> Void {
    if pos(",", value) >= 0 {
        mstreamappendbyte(ms, ord("\""));
        appendText(ms, value);
        mstreamappendbyte(ms, ord("\""));
    } else {
        appendText(ms, value);
    }
    ret;
}

fn main() -> Void {
    let payload: MStream = mstreamfromstring("[{\"sku\":\"A-1\",\"name\":\"Lamp\",\"stock\":3},{\"sku\":\"B-7\",\"name\":\"Desk, oak\",\"stock\":0},{\"sku\":\"C-2\",\"name\":\"Chair\",\"stock\":12}]");
    let doc: ToonDoc = toon_parse(mstreambuffer(payload));
