    let root: ToonNode = toon_root(doc);
    let csv: MStream = mstreamcreate();
    appendText(csv, "sku,name,stock");
    mstreamappendbyte(csv, 10);
    let empty: Int = 0;
    loop item in root {
        let sku: Text = toon_get_text(item, "sku");
        let name: Text = toon_get_text(item, "name");
        let stock: Int = toon_get_int(item, "stock");
        appendField(csv, sku);
        mstreamappendbyte(csv, ord(","));
        appendField(csv, name);
        mstreamappendbyte(csv, ord(","));
        appendText(csv, int_to_text(stock));
        mstreamappendbyte(csv, 10);
        if stock == 0 {
            empty = empty + 1;
        }
    }
    fx {
        print(mstreambuffer(csv));
        println("out_of_stock=", empty);
    }
    mstreamfree(csv);
    toon_close(doc);
    ret;
