fn main() -> Void {
    let src: MStream = mstreamcreate();
    fx {
        mstreamloadfromfile(src, "users.json");
    }
    let doc: ToonDoc = toon_parse(mstreambuffer(src));
    mstreamfree(src);
    let users: ToonNode = toon_key(toon_root(doc), "users");
    let missing: MStream = mstreamcreate();
    let gaps: Int = 0;
    fx {
        loop i in 0..toon_len(users) {
            let u: ToonNode = toon_at(users, i);
            let name: Text = toon_get_text_or(u, "name", "?");
            let email: Text = toon_get_text_or(u, "email", "-");
            println("name=", name, " age=", toon_get_int_or(u, "age", 0), " email=", email);
            if email == "-" {
                if gaps > 0 {
                    mstreamappendbyte(missing, ord(","));
                }
                appendText(missing, name);
                gaps = gaps + 1;
            }
        }
        println("missing_email=", mstreambuffer(missing));
    }
    mstreamfree(missing);
    toon_close(doc);
    ret;
}
